<?php require_once __DIR__ . '/../conexion.php';$r=$conexion->query("SELECT m.idmateria,m.descripcion_mat,m.estatus_mat,COUNT(am.idalumn) AS cantidad FROM materias m LEFT JOIN asignar_materia am ON m.idmateria=am.idmateria GROUP BY m.idmateria,m.descripcion_mat,m.estatus_mat ORDER BY m.descripcion_mat");?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lista de materias</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="../index.php" class="btn btn-secondary mb-3 d-print-none">Volver al menú</a><h2>Lista de materias</h2><table class="table table-bordered table-striped"><thead class="table-dark"><tr><th>ID</th><th>Materia</th><th>Cantidad de alumnos</th><th>Estatus</th></tr></thead><tbody><?php while($f=$r->fetch_assoc()):?><tr><td><?php echo $f['idmateria'];?></td><td><?php echo htmlspecialchars($f['descripcion_mat']);?></td><td><?php echo $f['cantidad'];?></td><td><?php echo $f['estatus_mat'];?></td></tr><?php endwhile;?></tbody></table><button onclick="print()" class="btn btn-primary d-print-none">Imprimir</button></main></body></html>
